"use client"

import * as React from "react"
import { Sheet as ScrollSheet, type DetentSpec } from "scrollsheet"

import { cn } from "@/lib/utils"

// shadcn's sheet puts `side` on SheetContent; scrollsheet anchors the whole
// root, so it lives here. Defaults to the right edge like shadcn's sheet.
function Sheet({
  side = "right",
  ...props
}: React.ComponentProps<typeof ScrollSheet.Root>) {
  return <ScrollSheet.Root data-slot="sheet" side={side} {...props} />
}

function SheetTrigger({
  ...props
}: React.ComponentProps<typeof ScrollSheet.Trigger>) {
  return <ScrollSheet.Trigger data-slot="sheet-trigger" {...props} />
}

function SheetContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof ScrollSheet.Content>) {
  return (
    <ScrollSheet.Content
      data-slot="sheet-content"
      className={cn("bg-background shadow-lg", className)}
      {...props}
    >
      {children}
    </ScrollSheet.Content>
  )
}

function SheetHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-header"
      className={cn("flex flex-col gap-1.5 p-4", className)}
      {...props}
    />
  )
}

function SheetFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sheet-footer"
      className={cn("mt-auto flex flex-col gap-2 p-4", className)}
      {...props}
    />
  )
}

function SheetTitle({
  className,
  ...props
}: React.ComponentProps<typeof ScrollSheet.Title>) {
  return (
    <ScrollSheet.Title
      data-slot="sheet-title"
      className={cn("text-foreground font-semibold", className)}
      {...props}
    />
  )
}

function SheetDescription({
  className,
  ...props
}: React.ComponentProps<typeof ScrollSheet.Description>) {
  return (
    <ScrollSheet.Description
      data-slot="sheet-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  )
}

function SheetClose({
  className,
  ...props
}: React.ComponentProps<typeof ScrollSheet.Close>) {
  return (
    <ScrollSheet.Close
      data-slot="sheet-close"
      className={cn(
        "text-foreground/70 hover:text-foreground absolute top-4 right-4 text-sm underline-offset-4 hover:underline",
        className
      )}
      {...props}
    />
  )
}

export {
  Sheet,
  SheetTrigger,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
  SheetClose,
  type DetentSpec,
}
